from abc import abstractmethod, ABCMeta
from logging import Logger
import time
from os.path import basename
from socket import error as socket_error
from six import with_metaclass

from ta_egate_cmd_parser import ta_egate_cmd_parser, egate_connection_registry
from ta_egate_cmd_parser.egate_command_base import CommandExecutionFailed
from ta_egate_cmd_parser.egate_connection import get_connection


class EgateInterface(with_metaclass(ABCMeta)):
    def __init__(self, configuration, **kwargs):
        # type: (dict, Optional[Dict[str, Any]]) -> None
        """
        Plugin to gather logs from EPC and I-PHY (WTS)
        :param log_host: IP address of self._logger host
        :param log_port: port of self._logger host
        :param configuration:
        """
        self._logger = Logger("LC")
        self._log_dir = kwargs.pop("log_dir")
        self._configuration = configuration
        self._egate_id = -1
        self._egate_cmd_parser = ta_egate_cmd_parser()
        self._backup_values = {}  # type: Dict[str, Any]

    def __enter__(self):
        self._logger.info("inside {} before start".format(basename(__file__)))
        self.start()
        self._logger.info("inside {} after start".format(basename(__file__)))

    def __exit__(self, exc_type, exc_val, exc_tb):
        self._logger.info("inside {} before stop".format(basename(__file__)))
        self.stop()
        self._logger.info("inside {} after stop".format(basename(__file__)))

    @property
    def egate_id(self):
        # type: () -> int
        """
        Property to get egate ID.

        :return: egate identification
        """
        if self._egate_id == -1:
            host, port = self._get_egate_config()
            self._logger.debug("EGATE config provided: ({}:{})".format(host, port))
            if host not in ("localhost", "127.0.0.1") or port != 20000:
                self._logger.debug("Creating new EGATE connection registry")
                egate_connection_registry.add_to_registry(1, host, port)
                self._egate_id = 1
            else:
                self._egate_id = 0
            self._logger.debug("Returning self._egate_id = {}".format(self._egate_id))
        return self._egate_id

    def _check_egate_connectivity(self, egate_id):
        """Check if EGATE telnet is working"""
        for sleep_time in 15 * [1]:
            try:
                egate_conn = get_connection(egate_id)
                egate_conn.close()
                return True
            except Exception as err:
                self._logger.debug(err, exc_info=True)
                time.sleep(sleep_time)
        return False

    def _execute_egate_command(self, cmd, **params):
        # type: (str, Union[Dict[str, Any], str, int, EPCLogLevel]) -> None
        """
        Executes EGATE command via egate_cmd_parser
        :param cmd: command to be executed
        :param params: params for command
        :return: output of executed command
        """
        try:
            if not self._check_egate_connectivity(self.egate_id):
                self._logger.debug("Egate not responding. '{} {}' will not be invoked".format(cmd, params))
                return
            self._logger.debug("Sending EGATE command: {} {}".format(cmd, params))
            self._egate_cmd_parser.run_command(cmd, egate_id=self.egate_id, **params)
            self._logger.debug("EGATE command '{} {}' executed successfully".format(cmd, params))
        except CommandExecutionFailed as err:
            self._logger.error("Failed to execute epcsim command: [{}]".format(err), exc_info=True)
        except socket_error as err:
            self._logger.error(
                "Connection to EGATE refused. Probably epcsim not started or host address/port is wrong. [{}]".format(
                    err
                ),
                exc_info=True,
            )

    def _get_egate_config(self):
        # type: () -> Tuple[str, int]
        return self._configuration["egate_host"], self._configuration["egate_port"]

    @abstractmethod
    def start(self):
        pass

    @abstractmethod
    def stop(self):
        pass
